update public.site_content set hero_story_line_1 = 'Irving''s neighborhood Vietnamese kitchen.', story_body = 'Phở Empire started with one simple belief — that great phở takes time, care, and a family recipe worth sharing. We''ve been serving Irving, Texas, and every bowl we serve comes from the same recipe we make at home. We''re located in Irving, just a short drive from Las Colinas, Coppell, and the rest of the DFW area.' where id = 1;